11	
12	
13	// ============================================================
14	// Elementwise 算子 op_kernel 模板
15	// 适用: ReLU, GELU, Add, Mul 等逐元素算子
16	// 使用: 复制到 csrc/ops/<op_name>/op_kernel/<op_name>.cpp，
17	//       替换 <op_name>/<OpName> 占位符，修改 Compute 逻辑
18	// ============================================================
19	
20	#include "kernel_operator.h"
21	
22	constexpr int32_t BUFFER_NUM = 2;
23	
24	template <typename T>
25	class Kernel<OpName> {
26	public:
27	    __aicore__ inline Kernel<OpName>() {}
28	
29	    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y,
30	                                int64_t formerNum, int64_t formerLength,
31	                                int64_t tailLength, int64_t tileLength)
32	    {
33	        int64_t blockIdx = AscendC::GetBlockIdx();
34	
35	        if (blockIdx < formerNum) {
36	            this->blockLength = formerLength;
37	            int64_t offset = formerLength * blockIdx;
38	            xGm.SetGlobalBuffer((__gm__ T *)x + offset, formerLength);
39	            yGm.SetGlobalBuffer((__gm__ T *)y + offset, formerLength);
40	        } else {
41	            this->blockLength = tailLength;
42	            int64_t tailIdx = blockIdx - formerNum;
43	            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
44	            xGm.SetGlobalBuffer((__gm__ T *)x + offset, tailLength);
45	            yGm.SetGlobalBuffer((__gm__ T *)y + offset, tailLength);
46	        }
47	
48	        this->tileLength = tileLength;
49	
50	        pipe.InitBuffer(inQueueX, BUFFER_NUM, tileLength * sizeof(T));
51	        pipe.InitBuffer(outQueueY, BUFFER_NUM, tileLength * sizeof(T));
52	        // 如需升精度计算 (FP16/BF16), 添加 FP32 临时缓冲:pipe.InitBuffer(tmpBuf, tileLength * sizeof(float));
53	    }
54	
55	    __aicore__ inline void Process()
56	    {
57	        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
58	        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;
59	
60	        int64_t alignNum = 32 / static_cast<int64_t>(sizeof(T));
61	        int64_t alignedTailLen = ((tailTileLength + alignNum - 1) / alignNum) * alignNum;
62	
63	        for (int64_t i = 0; i < tileNum - 1; ++i) {
64	            CopyIn(i, this->tileLength);
65	            Compute(i, this->tileLength);
66	            CopyOut(i, this->tileLength);
67	        }
68	        if (tileNum > 0) {
69	            CopyIn(tileNum - 1, alignedTailLen);
70	            Compute(tileNum - 1, alignedTailLen);
71	            CopyOut(tileNum - 1, alignedTailLen);
72	        }
73	    }
74	
75	private:
76	    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
77	    {
78	        AscendC::LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
79	        AscendC::DataCopy(xLocal, xGm[progress * this->tileLength], curTileLength);
80	        inQueueX.EnQue(xLocal);
81	    }
82	
83	    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
84	    {
85	        AscendC::LocalTensor<T> xLocal = inQueueX.DeQue<T>();
86	        AscendC::LocalTensor<T> yLocal = outQueueY.AllocTensor<T>();
87	
88	        // ==== 在此填充计算逻辑 ====
89	        // 简单示例 (ReLU):
90	        //   AscendC::Relu(yLocal, xLocal, curTileLength);
91	        //
92	        // FP16/BF16 升精度示例:
93	        //   AscendC::LocalTensor<float> tmp = tmpBuf.Get<float>();
94	        //   AscendC::Cast(tmp, xLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
95	        //   // ... FP32 计算 ...
96	        //   AscendC::Cast(yLocal, tmp, AscendC::RoundMode::CAST_RINT, curTileLength);
97	
98	        outQueueY.EnQue<T>(yLocal);
99	        inQueueX.FreeTensor(xLocal);
100	    }
101	
102	    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
103	    {
104	        AscendC::LocalTensor<T> yLocal = outQueueY.DeQue<T>();
105	        AscendC::DataCopy(yGm[progress * this->tileLength], yLocal, curTileLength);
106	        outQueueY.FreeTensor(yLocal);
107	    }
108	
109	private:
110	    AscendC::TPipe pipe;
111	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
112	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueY;
113	    // AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf;  // FP32 临时缓冲
114	    AscendC::GlobalTensor<T> xGm;
115	    AscendC::GlobalTensor<T> yGm;
116	    int64_t blockLength;
117	    int64_t tileLength;
118	};
119	
120	extern "C" __global__ __aicore__ void <op_name>(GM_ADDR x, GM_ADDR y,
121	                                                 int64_t formerNum, int64_t formerLength,
122	                                                 int64_t tailLength, int64_t tileLength,
123	                                                 int64_t dtypeSize)
124	{
125	    if (dtypeSize == 2) {
126	        Kernel<OpName><half> op;
127	        op.Init(x, y, formerNum, formerLength, tailLength, tileLength);
128	        op.Process();
129	    } else {
130	        Kernel<OpName><float> op;
131	        op.Init(x, y, formerNum, formerLength, tailLength, tileLength);
132	        op.Process();
133	    }
134	}
135

