#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_equal_kernel.h"

namespace ascend_kernel {

constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;

// dtypeCategory mapping helper
static int64_t getDtypeCategory(at::ScalarType st) {
    switch (st) {
        case at::kHalf:      return 0;
        case at::kFloat:     return 1;
        case at::kBFloat16:  return 2;
        case at::kChar:      return 3;  // int8
        case at::kByte:      return 4;  // uint8
        case at::kInt:       return 5;
        default:
            TORCH_CHECK(false, "equal: unsupported dtype ", st);
            return -1;
    }
}

// bufferCoefficient lookup by dtypeCategory
static int64_t getBufferCoefficient(int64_t dtypeCategory) {
    switch (dtypeCategory) {
        case 0:  // float16
        case 2:  // bfloat16
            return 32;
        case 1:  // float32
            return 32;
        case 3:  // int8
        case 4:  // uint8
            return 28;
        case 5:  // int32
            return 32;
        default:
            return 32;
    }
}

at::Tensor equal(const at::Tensor &input1, const at::Tensor &input2)
{
    // ---- 输入校验 ----
    TORCH_CHECK(input1.scalar_type() == input2.scalar_type(),
                "equal: input1 and input2 must have the same dtype");
    TORCH_CHECK(input1.sizes() == input2.sizes(),
                "equal: input1 and input2 must have the same shape");

    at::ScalarType dtype = input1.scalar_type();
    TORCH_CHECK(dtype == at::kHalf || dtype == at::kFloat || dtype == at::kBFloat16 ||
                dtype == at::kChar || dtype == at::kByte || dtype == at::kInt,
                "equal: only float16, float32, bfloat16, int8, uint8, int32 are supported, got ", dtype);

    int64_t totalLength = input1.numel();
    auto output = at::empty(input1.sizes(), input1.options().dtype(at::kInt));

    if (totalLength == 0) {
        return output;
    }

    int64_t dtypeSize = input1.element_size();
    int64_t dtypeCategory = getDtypeCategory(dtype);

    // ---- 获取硬件参数 ----
    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);

    // ---- Block 级 tiling (核间切分, Cache Line 对齐) ----
    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
    int64_t totalLengthCoreAlign = (totalLengthCore + CACHE_LINE_BYTE_LENGTH - 1)
                                    / CACHE_LINE_BYTE_LENGTH * CACHE_LINE_BYTE_LENGTH;

    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
    int64_t formerNum = usedCoreNum - 1;
    int64_t formerLength = totalLengthCoreAlign;
    int64_t tailLength = totalLength - formerNum * formerLength;

    // ---- UB 级 tiling (核内切分) ----
    int64_t bufferCoefficient = getBufferCoefficient(dtypeCategory);
    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;

    // 32B alignment first
    int64_t alignElements = 32 / static_cast<int64_t>(sizeof(int32_t));  // align to output type size
    int64_t tileLength = (maxTileElements / alignElements) * alignElements;

    // 256B alignment for Compare API (operates on 4-byte types after Cast)
    int64_t compareAlignElements = 256 / static_cast<int64_t>(sizeof(int32_t));  // = 64
    tileLength = (tileLength / compareAlignElements) * compareAlignElements;

    if (tileLength == 0) {
        tileLength = compareAlignElements;
    }

    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    // 所有参数必须是左值
    int64_t formerNumVal = formerNum;
    int64_t formerLengthVal = formerLength;
    int64_t tailLengthVal = tailLength;
    int64_t tileLengthVal = tileLength;
    int64_t dtypeSizeVal = dtypeSize;
    int64_t dtypeCategoryVal = dtypeCategory;

    EXEC_KERNEL_CMD(equal_kernel, blockDim,
                    input1, input2, output,
                    formerNumVal, formerLengthVal, tailLengthVal, tileLengthVal,
                    dtypeSizeVal, dtypeCategoryVal);

    return output;
}

