#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

template <typename T>
class KernelEqual {
public:
    __aicore__ inline KernelEqual() {}

    __aicore__ inline void Init(
        GM_ADDR input1, GM_ADDR input2, GM_ADDR output,
        int64_t formerNum, int64_t formerLength,
        int64_t tailLength, int64_t tileLength)
    {
        int64_t blockIdx = AscendC::GetBlockIdx();

        if (blockIdx < formerNum) {
            this->blockLength = formerLength;
            int64_t offset = formerLength * blockIdx;
            input1Gm_.SetGlobalBuffer((__gm__ T *)input1 + offset, formerLength);
            input2Gm_.SetGlobalBuffer((__gm__ T *)input2 + offset, formerLength);
            outputGm_.SetGlobalBuffer((__gm__ int32_t *)output + offset, formerLength);
        } else {
            this->blockLength = tailLength;
            int64_t tailIdx = blockIdx - formerNum;
            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
            input1Gm_.SetGlobalBuffer((__gm__ T *)input1 + offset, tailLength);
            input2Gm_.SetGlobalBuffer((__gm__ T *)input2 + offset, tailLength);
            outputGm_.SetGlobalBuffer((__gm__ int32_t *)output + offset, tailLength);
        }

        this->tileLength = tileLength;

        // Double buffer queues
        pipe_.InitBuffer(inQueueX_, BUFFER_NUM, tileLength * sizeof(T));
        pipe_.InitBuffer(inQueueY_, BUFFER_NUM, tileLength * sizeof(T));
        pipe_.InitBuffer(outQueueZ_, BUFFER_NUM, tileLength * sizeof(int32_t));

        // Compare result buffer: ceil(tileLength/8) uint8_t elements, 32B aligned
        int64_t cmpBufElem = ((tileLength + 7) / 8 + 31) / 32 * 32;
        pipe_.InitBuffer(cmpBuf_, cmpBufElem * sizeof(uint8_t));

        // Select one-buffer: tileLength int32_t elements
        pipe_.InitBuffer(oneBuf_, tileLength * sizeof(int32_t));

        // Cast buffers for fp16/bf16/int8/uint8 (convert to float/int32 for comparison)
        if constexpr (std::is_same_v<T, half> || std::is_same_v<T, bfloat16_t>) {
            pipe_.InitBuffer(castBufX_, tileLength * sizeof(float));
            pipe_.InitBuffer(castBufY_, tileLength * sizeof(float));
        } else if constexpr (std::is_same_v<T, int8_t> || std::is_same_v<T, uint8_t>) {
            pipe_.InitBuffer(castBufX_, tileLength * sizeof(int32_t));
            pipe_.InitBuffer(castBufY_, tileLength * sizeof(int32_t));
        }
    }

    __aicore__ inline void Process()
    {
        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;

        for (int64_t i = 0; i < tileNum - 1; ++i) {
            CopyIn(i, this->tileLength);
            Compute(i, this->tileLength);
            CopyOut(i, this->tileLength);
        }
        if (tileNum > 0) {
            CopyIn(tileNum - 1, tailTileLength);
            Compute(tileNum - 1, tailTileLength);
            CopyOut(tileNum - 1, tailTileLength);
        }
    }

private:
    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> xLocal = inQueueX_.AllocTensor<T>();
        AscendC::DataCopyParams copyParams = {1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0};
        AscendC::DataCopyPadParams padParams = {false, 0, 0, 0};
        AscendC::DataCopyPad(xLocal, input1Gm_[progress * this->tileLength], copyParams, padParams);
        inQueueX_.EnQue(xLocal);

        AscendC::LocalTensor<T> yLocal = inQueueY_.AllocTensor<T>();
        AscendC::DataCopyPad(yLocal, input2Gm_[progress * this->tileLength], copyParams, padParams);
        inQueueY_.EnQue(yLocal);
    }

    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> xLocal = inQueueX_.DeQue<T>();
        AscendC::LocalTensor<T> yLocal = inQueueY_.DeQue<T>();
        AscendC::LocalTensor<int32_t> outLocal = outQueueZ_.AllocTensor<int32_t>();

        // --- Comparison: use Sub + Abs on correctly typed data, then threshold ---

        if constexpr (std::is_same_v<T, float>) {
            // float32: direct comparison via Sub+Abs -> where |diff| < eps
            computeEqFloat32(outLocal, xLocal, yLocal, curTileLength);
        } else if constexpr (std::is_same_v<T, half>) {
            // float16: cast to float32, then compare
            AscendC::LocalTensor<float> xFp32 = castBufX_.Get<float>(curTileLength);
            AscendC::LocalTensor<float> yFp32 = castBufY_.Get<float>(curTileLength);
            AscendC::Cast(xFp32, xLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
            AscendC::Cast(yFp32, yLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
            computeEqFloat32(outLocal, xFp32, yFp32, curTileLength);
        } else if constexpr (std::is_same_v<T, bfloat16_t>) {
            // bfloat16: cast to float32, then compare
            AscendC::LocalTensor<float> xFp32 = castBufX_.Get<float>(curTileLength);
            AscendC::LocalTensor<float> yFp32 = castBufY_.Get<float>(curTileLength);
            AscendC::Cast(xFp32, xLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
            AscendC::Cast(yFp32, yLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
            computeEqFloat32(outLocal, xFp32, yFp32, curTileLength);
        } else if constexpr (std::is_same_v<T, int32_t>) {
            // int32: direct comparison
            computeEqInt32(outLocal, xLocal, yLocal, curTileLength);
        } else if constexpr (std::is_same_v<T, int8_t> || std::is_same_v<T, uint8_t>) {
            // int8/uint8: copy to int32 buffer, then compare
            AscendC::LocalTensor<int32_t> xI32 = castBufX_.Get<int32_t>(curTileLength);
            AscendC::LocalTensor<int32_t> yI32 = castBufY_.Get<int32_t>(curTileLength);
            // Use Duplicate+DataCopy pattern or simple cast
            AscendC::Cast(xI32, xLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
            AscendC::Cast(yI32, yLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
            computeEqInt32(outLocal, xI32, yI32, curTileLength);
        }

        outQueueZ_.EnQue<int32_t>(outLocal);
        inQueueX_.FreeTensor(xLocal);
        inQueueY_.FreeTensor(yLocal);
    }

    __aicore__ inline void computeEqFloat32(
        AscendC::LocalTensor<int32_t> &outLocal,
        AscendC::LocalTensor<float> &xLocal,
        AscendC::LocalTensor<float> &yLocal,
        int64_t curTileLength)
    {
        // diff = x - y
        // abs_diff = |diff|
        // Compare: abs_diff == 0 within float tolerance
        // For float, use Compare API with EQ mode
        AscendC::LocalTensor<uint8_t> cmpResult = cmpBuf_.Get<uint8_t>();
        AscendC::Compare(cmpResult, xLocal, yLocal, AscendC::CMPMODE::EQ, curTileLength);

        AscendC::LocalTensor<int32_t> oneLocal = oneBuf_.Get<int32_t>(curTileLength);
        AscendC::Duplicate(oneLocal, (int32_t)1, curTileLength);
        AscendC::Select(outLocal, cmpResult, oneLocal, (int32_t)0,
                        AscendC::SELMODE::VSEL_TENSOR_SCALAR_MODE, curTileLength);
    }

    __aicore__ inline void computeEqInt32(
        AscendC::LocalTensor<int32_t> &outLocal,
        AscendC::LocalTensor<int32_t> &xLocal,
        AscendC::LocalTensor<int32_t> &yLocal,
        int64_t curTileLength)
    {
        AscendC::LocalTensor<uint8_t> cmpResult = cmpBuf_.Get<uint8_t>();
        AscendC::Compare(cmpResult, xLocal, yLocal, AscendC::CMPMODE::EQ, curTileLength);

        AscendC::LocalTensor<int32_t> oneLocal = oneBuf_.Get<int32_t>(curTileLength);
        AscendC::Duplicate(oneLocal, (int32_t)1, curTileLength);
        AscendC::Select(outLocal, cmpResult, oneLocal, (int32_t)0,
                        AscendC::SELMODE::VSEL_TENSOR_SCALAR_MODE, curTileLength);
    }

    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<int32_t> outLocal = outQueueZ_.DeQue<int32_t>();
        AscendC::DataCopyParams copyParams = {1, static_cast<uint32_t>(curTileLength * sizeof(int32_t)), 0, 0};
        AscendC::DataCopyPad(outputGm_[progress * this->tileLength], outLocal, copyParams);
        outQueueZ_.FreeTensor(outLocal);
    }

private:
    AscendC::TPipe pipe_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueY_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueZ_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> cmpBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> oneBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> castBufX_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> castBufY_;
    AscendC::GlobalTensor<T> input1Gm_;
    AscendC::GlobalTensor<T> input2Gm_;
    AscendC::GlobalTensor<int32_t> outputGm_;
    int64_t blockLength;
    int64_t tileLength;
};

extern "C" __global__ __aicore__ void equal_kernel(
    GM_ADDR input1, GM_ADDR input2, GM_ADDR output,
    int64_t formerNum, int64_t formerLength,
    int64_t tailLength, int64_t tileLength,
    int64_t dtypeSize, int64_t dtypeCategory)
{
    // dtypeCategory: 0=float16, 1=float32, 2=bfloat16, 3=int8, 4=uint8, 5=int32
    if (dtypeCategory == 0) {
        KernelEqual<half> op;
        op.Init(input1, input2, output, formerNum, formerLength, tailLength, tileLength);
        op.Process();
    } else if (dtypeCategory == 1) {
        KernelEqual<float> op;
        op.Init(input1, input2, output, formerNum, formerLength, tailLength, tileLength);
        op.Process();
    } else if (dtypeCategory == 2) {
        KernelEqual<bfloat16_t> op;
        op.Init(input1, input2, output, formerNum, formerLength, tailLength, tileLength);
        op.Process();
    } else if (dtypeCategory == 3) {
        KernelEqual<int8_t> op;
        op.Init(input1, input2, output, formerNum, formerLength, tailLength, tileLength);
        op.Process();
    } else if (dtypeCategory == 4) {
        KernelEqual<uint8_t> op;
        op.Init(input1, input2, output, formerNum, formerLength, tailLength, tileLength);
        op.Process();
    } else {
        KernelEqual<int32_t> op;
        op.Init(input1, input2, output, formerNum, formerLength, tailLength, tileLength);
        op.Process();
    }
}
