        this->tileLength = tileLength;

        // Double buffer queues for input and output
        pipe_.InitBuffer(inQueueX_, BUFFER_NUM, tileLength * sizeof(T));
        pipe_.InitBuffer(inQueueY_, BUFFER_NUM, tileLength * sizeof(T));
        pipe_.InitBuffer(outQueueZ_, BUFFER_NUM, tileLength * sizeof(int32_t));
    }

    __aicore__ inline void Process()
    {
        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;
        int64_t curTileLength;

        for (int64_t i = 0; i < tileNum; ++i) {
            curTileLength = (i == tileNum - 1) ? tailTileLength : this->tileLength;
            CopyIn(i, curTileLength);
            Compute(i, curTileLength);
            CopyOut(i, curTileLength);
        }
    }

private:
    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> xLocal = inQueueX_.AllocTensor<T>();
        AscendC::DataCopyExtParams copyParams{1,
                                              static_cast<uint32_t>(curTileLength) * static_cast<uint32_t>(sizeof(T)),
                                              0, 0, 0};
        AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
        AscendC::DataCopyPad(xLocal, input1Gm_[progress * this->tileLength], copyParams, padParams);
        inQueueX_.EnQue(xLocal);

        AscendC::LocalTensor<T> yLocal = inQueueY_.AllocTensor<T>();
        AscendC::DataCopyPad(yLocal, input2Gm_[progress * this->tileLength], copyParams, padParams);
        inQueueY_.EnQue(yLocal);
    }

    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> xLocal = inQueueX_.DeQue<T>();
        AscendC::LocalTensor<T> yLocal = inQueueY_.DeQue<T>();
        AscendC::LocalTensor<int32_t> outLocal = outQueueZ_.AllocTensor<int32_t>();

        if constexpr (std::is_same_v<T, half> || std::is_same_v<T, bfloat16_t>) {
            // Allocate float32 temp buffers for fp16/bf16 upcast
            AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf;
            int64_t tmpBufSize = curTileLength * sizeof(float) * 2;
            pipe_.InitBuffer(tmpBuf, tmpBufSize);
            AscendC::LocalTensor<float> xFp32 = tmpBuf.Get<float>(curTileLength);
            AscendC::LocalTensor<float> yFp32 = tmpBuf.Get<float>((int32_t)(curTileLength * sizeof(float)));
            AscendC::Cast(xFp32, xLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
            AscendC::Cast(yFp32, yLocal, AscendC::RoundMode::CAST_NONE, curTileLength);

            // Element-wise compare using Sub + Abs + threshold for float equality
            AscendC::LocalTensor<float> diffFp32 = tmpBuf.Get<float>(curTileLength);
            AscendC::Sub(diffFp32, xFp32, yFp32, curTileLength);
            AscendC::Abs(diffFp32, diffFp32, curTileLength);

            // diffFp32 < epsilon → equal (=1), else → not equal (=0)
            // Use Compare with small epsilon value
            AscendC::TBuf<AscendC::TPosition::VECCALC> cmpBuf;
            int64_t cmpBufElem = ((curTileLength + 7) / 8 + 31) / 32 * 32;
            pipe_.InitBuffer(cmpBuf, cmpBufElem * sizeof(uint8_t));
            AscendC::LocalTensor<uint8_t> cmpResult = cmpBuf.Get<uint8_t>(cmpBufElem);

            AscendC::TBuf<AscendC::TPosition::VECCALC> epsBuf;
            pipe_.InitBuffer(epsBuf, curTileLength * sizeof(float));
            AscendC::LocalTensor<float> epsLocal = epsBuf.Get<float>(curTileLength);
            AscendC::Duplicate(epsLocal, 1e-6f, curTileLength);
            AscendC::Compare(cmpResult, diffFp32, epsLocal, AscendC::CMPMODE::LT, curTileLength);

            AscendC::TBuf<AscendC::TPosition::VECCALC> oneBuf;
            pipe_.InitBuffer(oneBuf, curTileLength * sizeof(int32_t));
            AscendC::LocalTensor<int32_t> oneLocal = oneBuf.Get<int32_t>(curTileLength);
            AscendC::Duplicate(oneLocal, (int32_t)1, curTileLength);
            AscendC::Select(outLocal, cmpResult, oneLocal, (int32_t)0,
                            AscendC::SELMODE::VSEL_TENSOR_SCALAR_MODE, curTileLength);
        } else {
            // Integer types (float32, int32, int8, uint8): direct comparison using
            // Sub + Abs approach: x==y iff (x-y)==0 iff |x-y|==0
            AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf;
            pipe_.InitBuffer(tmpBuf, curTileLength * sizeof(T) * 2);
            AscendC::LocalTensor<T> diffBuf = tmpBuf.Get<T>(curTileLength);
            AscendC::LocalTensor<T> absBuf = tmpBuf.Get<T>((int32_t)(curTileLength * sizeof(T)));

            AscendC::Sub(diffBuf, xLocal, yLocal, curTileLength);
            AscendC::Abs(absBuf, diffBuf, curTileLength);

            // Fill with ones, then use AscendC::Div to get: 1 where diff==0, 0 where diff!=0
            // Approach: for each element, if abs == 0 → Div(1, 1)=1, else Div(1, abs+1) ~=0
            // Simpler: use Sub(1, min(abs, 1)) → 1 where abs==0, 0 where abs>=1
            AscendC::LocalTensor<T> oneBuf = tmpBuf.Get<T>(curTileLength);
            AscendC::Duplicate(oneBuf, (T)1, curTileLength);

            // min(abs, 1) → clamps abs to [0, 1]
            AscendC::LocalTensor<T> clampedBuf = tmpBuf.Get<T>(curTileLength);
            AscendC::Min(clampedBuf, absBuf, oneBuf, curTileLength);

            // result = 1 - clamped → 1 where abs==0, 0 where abs>0
            AscendC::Sub(clampedBuf, oneBuf, clampedBuf, curTileLength);

            // Cast T result → int32 output
            // For T=float32, direct Cast works
            // For T=int32, direct Cast works
            // For T=int8/uint8: Cast to int32 is not supported
            // Workaround: use Duplicate to zero out oneBuf, then copy/convert
            if constexpr (std::is_same_v<T, float> || std::is_same_v<T, int32_t>) {
                AscendC::Cast(outLocal, clampedBuf, AscendC::RoundMode::CAST_NONE, curTileLength);
            } else {
                // int8/uint8: manual conversion using Select-like approach
                // Since Cast isn't available, reinterpret cast via DataCopy
                AscendC::TBuf<AscendC::TPosition::VECCALC> outTmpBuf;
                pipe_.InitBuffer(outTmpBuf, curTileLength * sizeof(int32_t));
                AscendC::LocalTensor<int32_t> outTmp = outTmpBuf.Get<int32_t>(curTileLength);
                AscendC::Cast(outTmp, clampedBuf, AscendC::RoundMode::CAST_NONE, curTileLength);
                AscendC::Duplicate(outLocal, outTmp, curTileLength);
                // Note: this ^ uses Duplicate which needs vector mode
            }
        }

        outQueueZ_.EnQue<int32_t>(outLocal);
        inQueueX_.FreeTensor(xLocal);
        inQueueY_.FreeTensor(yLocal);
    }

    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<int32_t> outLocal = outQueueZ_.DeQue<int32_t>();
        AscendC::DataCopyExtParams copyParams{1,
                                              static_cast<uint32_t>(curTileLength) * static_cast<uint32_t>(sizeof(int32_t)),
                                              0, 0, 0};
        AscendC::DataCopyPad(outputGm_[progress * this->tileLength], outLocal, copyParams);
        outQueueZ_.FreeTensor(outLocal);
    }

private:
    AscendC::TPipe pipe_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueY_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueZ_;
    AscendC::GlobalTensor<T> input1Gm_;
    AscendC::GlobalTensor<T> input2Gm_;
    AscendC::GlobalTensor<int32_t> outputGm_;
    int64_t blockLength;
    int64_t tileLength;
};

