            pipe_.InitBuffer(castBufXHalf_, tileLength * sizeof(half));
            pipe_.InitBuffer(castBufYHalf_, tileLength * sizeof(half));
            pipe_.InitBuffer(castBufX_, tileLength * sizeof(float));
            pipe_.InitBuffer(castBufY_, tileLength * sizeof(float));
