                            AscendC::SELMODE::VSEL_TENSOR_SCALAR_MODE, curTileLength);
        }
        else if constexpr (std::is_same_v<T, int8_t> || std::is_same_v<T, uint8_t>) {
            // int8/uint8 → half → float32 → Compare
            AscendC::LocalTensor<half> xHalf = castBufXHalf_.Get<half>(curTileLength);
            AscendC::LocalTensor<half> yHalf = castBufYHalf_.Get<half>(curTileLength);
            AscendC::Cast(xHalf, xLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
            AscendC::Cast(yHalf, yLocal, AscendC::RoundMode::CAST_NONE, curTileLength);

            AscendC::LocalTensor<float> xFp32 = castBufX_.Get<float>(curTileLength);
            AscendC::LocalTensor<float> yFp32 = castBufY_.Get<float>(curTileLength);
            AscendC::Cast(xFp32, xHalf, AscendC::RoundMode::CAST_NONE, curTileLength);
            AscendC::Cast(yFp32, yHalf, AscendC::RoundMode::CAST_NONE, curTileLength);

