        int64_t blockIdx = AscendC::GetBlockIdx();

        if (blockIdx < formerNum) {
            this->blockLength = formerLength;
            int64_t offset = formerLength * blockIdx;
            input1Gm_.SetGlobalBuffer((__gm__ T *)input1 + offset, formerLength);
            input2Gm_.SetGlobalBuffer((__gm__ T *)input2 + offset, formerLength);
            outputGm_.SetGlobalBuffer((__gm__ int32_t *)output + offset, formerLength);
        } else {
            this->blockLength = tailLength;
            int64_t tailIdx = blockIdx - formerNum;
            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
            input1Gm_.SetGlobalBuffer((__gm__ T *)input1 + offset, tailLength);
            input2Gm_.SetGlobalBuffer((__gm__ T *)input2 + offset, tailLength);
            outputGm_.SetGlobalBuffer((__gm__ int32_t *)output + offset, tailLength);
        }

        this->tileLength = tileLength;

        pipe_.InitBuffer(inQueueX_, BUFFER_NUM, tileLength * sizeof(T));
        pipe_.InitBuffer(inQueueY_, BUFFER_NUM, tileLength * sizeof(T));
        pipe_.InitBuffer(outQueueZ_, BUFFER_NUM, tileLength * sizeof(int32_t));
        int64_t mLen = maskBufLen(tileLength);
        pipe_.InitBuffer(maskBuf_, mLen * sizeof(uint8_t));

        // Cast buffers: only needed for types that need upcasting before Compare
        if constexpr (std::is_same_v<T, half> || std::is_same_v<T, bfloat16_t>) {
            pipe_.InitBuffer(castBufX_, tileLength * sizeof(float));
            pipe_.InitBuffer(castBufY_, tileLength * sizeof(float));
