 * See LICENSE in the root of the software repository for the full text of the License.
 */

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

template <typename T>
class KernelEqual {
public:
    __aicore__ inline KernelEqual() {}

    __aicore__ inline void Init(
        GM_ADDR input1, GM_ADDR input2, GM_ADDR output,
        int64_t formerNum, int64_t formerLength,
        int64_t tailLength, int64_t tileLength)
    {
        int64_t blockIdx = AscendC::GetBlockIdx();

        if (blockIdx < formerNum) {
            this->blockLength = formerLength;
            int64_t offset = formerLength * blockIdx;
            input1Gm_.SetGlobalBuffer((__gm__ T *)input1 + offset, formerLength);
            input2Gm_.SetGlobalBuffer((__gm__ T *)input2 + offset, formerLength);
            outputGm_.SetGlobalBuffer((__gm__ int32_t *)output + offset, formerLength);
        } else {
            this->blockLength = tailLength;
            int64_t tailIdx = blockIdx - formerNum;
            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
            input1Gm_.SetGlobalBuffer((__gm__ T *)input1 + offset, tailLength);
            input2Gm_.SetGlobalBuffer((__gm__ T *)input2 + offset, tailLength);
            outputGm_.SetGlobalBuffer((__gm__ int32_t *)output + offset, tailLength);
        }

        this->tileLength = tileLength;

        // I/O double buffer queues
        pipe_.InitBuffer(inQueueX_, BUFFER_NUM, tileLength * sizeof(T));
        pipe_.InitBuffer(inQueueY_, BUFFER_NUM, tileLength * sizeof(T));
        pipe_.InitBuffer(outQueueZ_, BUFFER_NUM, tileLength * sizeof(int32_t));

        // Work buffers for computation: diffBuf + onesBuf = 2 * tileLength * sizeof(T)
        // For float16/bf16: cast to float32 needs 2*float buffers
        // For int8/uint8: cast through half needs 2*half + 2*float buffers
        if constexpr (std::is_same_v<T, float> || std::is_same_v<T, int32_t>) {
            pipe_.InitBuffer(workBuf_, tileLength * sizeof(T) * 2);
        } else if constexpr (std::is_same_v<T, half> || std::is_same_v<T, bfloat16_t>) {
            pipe_.InitBuffer(workBuf_, tileLength * sizeof(float) * 2);
        } else {
            // int8/uint8: route through half
            pipe_.InitBuffer(castHalfBufX_, tileLength * sizeof(half));
            pipe_.InitBuffer(castHalfBufY_, tileLength * sizeof(half));
            pipe_.InitBuffer(workBuf_, tileLength * sizeof(float) * 2);
        }
    }

    __aicore__ inline void Process()
    {
        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;
        int64_t curTileLength;

        for (int64_t i = 0; i < tileNum; ++i) {
            curTileLength = (i == tileNum - 1) ? tailTileLength : this->tileLength;
            CopyIn(i, curTileLength);
            Compute(i, curTileLength);
            CopyOut(i, curTileLength);
        }
    }

private:
    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> xLocal = inQueueX_.AllocTensor<T>();
        AscendC::DataCopyExtParams copyParams{1,
                                              static_cast<uint32_t>(curTileLength) * static_cast<uint32_t>(sizeof(T)),
                                              0, 0, 0};
        AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
        AscendC::DataCopyPad(xLocal, input1Gm_[progress * this->tileLength], copyParams, padParams);
        inQueueX_.EnQue(xLocal);

        AscendC::LocalTensor<T> yLocal = inQueueY_.AllocTensor<T>();
        AscendC::DataCopyPad(yLocal, input2Gm_[progress * this->tileLength], copyParams, padParams);
        inQueueY_.EnQue(yLocal);
    }

    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> xLocal = inQueueX_.DeQue<T>();
        AscendC::LocalTensor<T> yLocal = inQueueY_.DeQue<T>();
        AscendC::LocalTensor<int32_t> outLocal = outQueueZ_.AllocTensor<int32_t>();

        if constexpr (std::is_same_v<T, float>) {
            computeFloat(xLocal, yLocal, outLocal, curTileLength);
        } else if constexpr (std::is_same_v<T, int32_t>) {
            computeInt32(xLocal, yLocal, outLocal, curTileLength);
        } else if constexpr (std::is_same_v<T, half>) {
            AscendC::LocalTensor<float> xFp32 = workBuf_.Get<float>(curTileLength);
            // Get second buffer region: subscript past first region
            // workBuf_ holds 2*float blocks. Get returns start; subscript offsets.
            // Need: xFp32 at offset 0, yFp32 at offset curTileLength floats
            AscendC::LocalTensor<float> allFp32 = workBuf_.Get<float>(curTileLength * 2);
            AscendC::LocalTensor<float> xFp32b = allFp32;
            AscendC::LocalTensor<float> yFp32b = allFp32[curTileLength];
            AscendC::Cast(xFp32b, xLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
            AscendC::Cast(yFp32b, yLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
            computeFloatOnBufs(xFp32b, yFp32b, outLocal, curTileLength);
        } else if constexpr (std::is_same_v<T, bfloat16_t>) {
            AscendC::LocalTensor<float> allFp32 = workBuf_.Get<float>(curTileLength * 2);
            AscendC::LocalTensor<float> xFp32 = allFp32;
            AscendC::LocalTensor<float> yFp32 = allFp32[curTileLength];
            AscendC::Cast(xFp32, xLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
            AscendC::Cast(yFp32, yLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
            computeFloatOnBufs(xFp32, yFp32, outLocal, curTileLength);
        } else {
            // int8/uint8: Cast int8→half, then half→float32
            AscendC::LocalTensor<half> xHalf = castHalfBufX_.Get<half>(curTileLength);
            AscendC::LocalTensor<half> yHalf = castHalfBufY_.Get<half>(curTileLength);
            AscendC::Cast(xHalf, xLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
            AscendC::Cast(yHalf, yLocal, AscendC::RoundMode::CAST_NONE, curTileLength);

            AscendC::LocalTensor<float> allFp32 = workBuf_.Get<float>(curTileLength * 2);
            AscendC::LocalTensor<float> xFp32 = allFp32;
            AscendC::LocalTensor<float> yFp32 = allFp32[curTileLength];
            AscendC::Cast(xFp32, xHalf, AscendC::RoundMode::CAST_NONE, curTileLength);
            AscendC::Cast(yFp32, yHalf, AscendC::RoundMode::CAST_NONE, curTileLength);
            computeFloatOnBufs(xFp32, yFp32, outLocal, curTileLength);
        }

        outQueueZ_.EnQue<int32_t>(outLocal);
        inQueueX_.FreeTensor(xLocal);
        inQueueY_.FreeTensor(yLocal);
    }

    // Compute equality on float32 tensors: Sub → Abs → Min(1, abs) → Sub(1, result) → Cast(int32)
    __aicore__ inline void computeFloat(
        AscendC::LocalTensor<float> &xLocal,
        AscendC::LocalTensor<float> &yLocal,
        AscendC::LocalTensor<int32_t> &outLocal,
        int64_t curTileLength)
    {
        AscendC::LocalTensor<float> allWork = workBuf_.Get<float>(curTileLength * 2);
        AscendC::LocalTensor<float> diffBuf = allWork;
        AscendC::LocalTensor<float> onesBuf = allWork[curTileLength];

        AscendC::Sub(diffBuf, xLocal, yLocal, curTileLength);
        AscendC::Abs(diffBuf, diffBuf, curTileLength);
        AscendC::Duplicate(onesBuf, 1.0f, curTileLength);
        AscendC::Min(diffBuf, diffBuf, onesBuf, curTileLength);
        AscendC::Sub(onesBuf, onesBuf, diffBuf, curTileLength);
        AscendC::Cast(outLocal, onesBuf, AscendC::RoundMode::CAST_RINT, curTileLength);
    }

    // Compute equality using pre-cast float32 buffers (avoids re-allocating workBuf_)
    __aicore__ inline void computeFloatOnBufs(
        AscendC::LocalTensor<float> &xLocal,
        AscendC::LocalTensor<float> &yLocal,
        AscendC::LocalTensor<int32_t> &outLocal,
        int64_t curTileLength)
    {
        // Re-use xLocal and yLocal space for diff+ones since they're no longer needed as inputs
        // (xLocal and yLocal are the float32 buffers after Cast, we can overwrite them)
        AscendC::LocalTensor<float> diffBuf = xLocal;
        AscendC::LocalTensor<float> onesBuf = yLocal;

        AscendC::Sub(diffBuf, xLocal, yLocal, curTileLength);
        AscendC::Abs(diffBuf, diffBuf, curTileLength);
        AscendC::Duplicate(onesBuf, 1.0f, curTileLength);
        AscendC::Min(diffBuf, diffBuf, onesBuf, curTileLength);
        AscendC::Sub(onesBuf, onesBuf, diffBuf, curTileLength);
        AscendC::Cast(outLocal, onesBuf, AscendC::RoundMode::CAST_RINT, curTileLength);
    }

    // Compute equality on int32 tensors: Sub → Abs → Min(1, abs) → Sub(1, result)
    __aicore__ inline void computeInt32(
        AscendC::LocalTensor<int32_t> &xLocal,
        AscendC::LocalTensor<int32_t> &yLocal,
        AscendC::LocalTensor<int32_t> &outLocal,
        int64_t curTileLength)
    {
        AscendC::LocalTensor<int32_t> allWork = workBuf_.Get<int32_t>(curTileLength * 2);
        AscendC::LocalTensor<int32_t> diffBuf = allWork;
        AscendC::LocalTensor<int32_t> onesBuf = allWork[curTileLength];

        AscendC::Sub(diffBuf, xLocal, yLocal, curTileLength);
        AscendC::Abs(diffBuf, diffBuf, curTileLength);
        AscendC::Duplicate(onesBuf, (int32_t)1, curTileLength);
        AscendC::Min(diffBuf, diffBuf, onesBuf, curTileLength);
        AscendC::Sub(outLocal, onesBuf, diffBuf, curTileLength);
    }

    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<int32_t> outLocal = outQueueZ_.DeQue<int32_t>();
        AscendC::DataCopyExtParams copyParams{1,
                                              static_cast<uint32_t>(curTileLength) * static_cast<uint32_t>(sizeof(int32_t)),
                                              0, 0, 0};
        AscendC::DataCopyPad(outputGm_[progress * this->tileLength], outLocal, copyParams);
        outQueueZ_.FreeTensor(outLocal);
    }

private:
    AscendC::TPipe pipe_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueY_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueZ_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> workBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> castHalfBufX_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> castHalfBufY_;
    AscendC::GlobalTensor<T> input1Gm_;
    AscendC::GlobalTensor<T> input2Gm_;
    AscendC::GlobalTensor<int32_t> outputGm_;
    int64_t blockLength;
    int64_t tileLength;
};

extern "C" __global__ __aicore__ void equal_kernel(
    GM_ADDR input1, GM_ADDR input2, GM_ADDR output,
    int64_t formerNum, int64_t formerLength,
    int64_t tailLength, int64_t tileLength,
    int64_t dtypeSize, int64_t dtypeCategory)
{
    if (dtypeCategory == 0) {
        KernelEqual<half> op;
        op.Init(input1, input2, output, formerNum, formerLength, tailLength, tileLength);
        op.Process();
    } else if (dtypeCategory == 1) {
        KernelEqual<float> op;
        op.Init(input1, input2, output, formerNum, formerLength, tailLength, tileLength);
        op.Process();
    } else if (dtypeCategory == 2) {
        KernelEqual<bfloat16_t> op;
        op.Init(input1, input2, output, formerNum, formerLength, tailLength, tileLength);
        op.Process();
    } else if (dtypeCategory == 3) {
        KernelEqual<int8_t> op;
        op.Init(input1, input2, output, formerNum, formerLength, tailLength, tileLength);
        op.Process();
    } else if (dtypeCategory == 4) {
        KernelEqual<uint8_t> op;
        op.Init(input1, input2, output, formerNum, formerLength, tailLength, tileLength);
        op.Process();
    } else {
        KernelEqual<int32_t> op;
        op.Init(input1, input2, output, formerNum, formerLength, tailLength, tileLength);
        op.Process();
    }
}
