#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

// ============================================================================
// Float32 Equal kernel: Compare EQ using Sub+Abs+Min approach
// ============================================================================
struct EqualFloat32 {
    __aicore__ inline void Init(GM_ADDR in1, GM_ADDR in2, GM_ADDR out,
                                 int64_t fn, int64_t fl, int64_t tl, int64_t tlen);
    __aicore__ inline void Process();
    __aicore__ inline void CopyIn(int64_t p, int64_t len);
    __aicore__ inline void Compute(int64_t p, int64_t len);
    __aicore__ inline void CopyOut(int64_t p, int64_t len);

    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> qX, qY;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> qZ;
    AscendC::TBuf<AscendC::TPosition::VECCALC> workBuf;
    AscendC::GlobalTensor<float> gX, gY;
    AscendC::GlobalTensor<int32_t> gZ;
    int64_t blockLen, tileLen;
};

__aicore__ inline void EqualFloat32::Init(GM_ADDR in1, GM_ADDR in2, GM_ADDR out,
                                           int64_t fn, int64_t fl, int64_t tl, int64_t tlen) {
    int64_t bidx = AscendC::GetBlockIdx();
    if (bidx < fn) {
        blockLen = fl; int64_t off = fl * bidx;
        gX.SetGlobalBuffer((__gm__ float*)in1 + off, fl);
        gY.SetGlobalBuffer((__gm__ float*)in2 + off, fl);
        gZ.SetGlobalBuffer((__gm__ int32_t*)out + off, fl);
    } else {
        blockLen = tl; int64_t ti = bidx - fn; int64_t off = fl * fn + tl * ti;
        gX.SetGlobalBuffer((__gm__ float*)in1 + off, tl);
        gY.SetGlobalBuffer((__gm__ float*)in2 + off, tl);
        gZ.SetGlobalBuffer((__gm__ int32_t*)out + off, tl);
    }
    tileLen = tlen;
    pipe.InitBuffer(qX, BUFFER_NUM, tlen * sizeof(float));
    pipe.InitBuffer(qY, BUFFER_NUM, tlen * sizeof(float));
    pipe.InitBuffer(qZ, BUFFER_NUM, tlen * sizeof(int32_t));
    pipe.InitBuffer(workBuf, tlen * sizeof(float) * 2);
}

__aicore__ inline void EqualFloat32::Process() {
    int64_t tn = (blockLen + tileLen - 1) / tileLen;
    int64_t tail = blockLen - (tn - 1) * tileLen;
    for (int64_t i = 0; i < tn; ++i) {
        int64_t cur = (i == tn - 1) ? tail : tileLen;
        CopyIn(i, cur); Compute(i, cur); CopyOut(i, cur);
    }
}

__aicore__ inline void EqualFloat32::CopyIn(int64_t p, int64_t len) {
    AscendC::LocalTensor<float> x = qX.AllocTensor<float>();
    AscendC::DataCopyExtParams cp{1, (uint32_t)(len * 4), 0, 0, 0};
    AscendC::DataCopyPadExtParams<float> pp{true, 0, 0, 0.0f};
    AscendC::DataCopyPad(x, gX[p * tileLen], cp, pp); qX.EnQue(x);
    AscendC::LocalTensor<float> y = qY.AllocTensor<float>();
    AscendC::DataCopyPad(y, gY[p * tileLen], cp, pp); qY.EnQue(y);
}

__aicore__ inline void EqualFloat32::Compute(int64_t p, int64_t len) {
    AscendC::LocalTensor<float> x = qX.DeQue<float>();
    AscendC::LocalTensor<float> y = qY.DeQue<float>();
    AscendC::LocalTensor<int32_t> z = qZ.AllocTensor<int32_t>();
    AscendC::LocalTensor<float> w = workBuf.Get<float>(len * 2);
    AscendC::LocalTensor<float> diff = w, ones = w[len];
    AscendC::Sub(diff, x, y, len);
    AscendC::Abs(diff, diff, len);
    AscendC::Duplicate(ones, 1.0f, len);
    AscendC::Min(diff, diff, ones, len);
    AscendC::Sub(ones, ones, diff, len);
    AscendC::Cast(z, ones, AscendC::RoundMode::CAST_RINT, len);
    qZ.EnQue<int32_t>(z); qX.FreeTensor(x); qY.FreeTensor(y);
}

__aicore__ inline void EqualFloat32::CopyOut(int64_t p, int64_t len) {
    AscendC::LocalTensor<int32_t> z = qZ.DeQue<int32_t>();
    AscendC::DataCopyExtParams cp{1, (uint32_t)(len * 4), 0, 0, 0};
    AscendC::DataCopyPad(gZ[p * tileLen], z, cp); qZ.FreeTensor(z);
}

