#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

// Shared helpers
template <typename T>
__aicore__ inline void copyGmToUb(
    AscendC::LocalTensor<T> &dst, AscendC::GlobalTensor<T> &src,
    int64_t offset, int64_t count)
{
    AscendC::DataCopyExtParams cp{1, (uint32_t)(count * sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> pp{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src[offset], cp, pp);
}

__aicore__ inline void copyUbToGmI32(
    AscendC::GlobalTensor<int32_t> &dst, AscendC::LocalTensor<int32_t> &src,
    int64_t offset, int64_t count)
{
    AscendC::DataCopyExtParams cp{1, (uint32_t)(count * 4), 0, 0, 0};
    AscendC::DataCopyPad(dst[offset], src, cp);
}

// Mask buffer element count (uint8 byte mask from Compare)
__aicore__ inline int64_t maskLen(int64_t n) {
    return ((n + 7) / 8 + 31) / 32 * 32;
}

// ============================================================================
// FLoat32 / Int32: use Compare EQ → Select with ones/zeros buffer
// ============================================================================
template <typename T>
__aicore__ inline void doEqT(
    AscendC::LocalTensor<T> &x, AscendC::LocalTensor<T> &y,
    AscendC::LocalTensor<int32_t> &z,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &mBuf,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &oBuf,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &nBuf,
    int64_t len)
{
    int64_t mLen = maskLen(len);
    AscendC::LocalTensor<uint8_t> cmp = mBuf.Get<uint8_t>(mLen);
    AscendC::Compare(cmp, x, y, AscendC::CMPMODE::EQ, len);

    AscendC::LocalTensor<int32_t> ones = oBuf.Get<int32_t>(len);
    AscendC::Duplicate(ones, (int32_t)1, len);
    AscendC::LocalTensor<int32_t> zeros = nBuf.Get<int32_t>(len);
    AscendC::Duplicate(zeros, (int32_t)0, len);

    AscendC::Select(z, cmp, ones, zeros, AscendC::SELMODE::VSEL_TENSOR_TENSOR_MODE, len);
}

// ============================================================================
// Half / BFloat16: Cast to float32 → Compare
// ============================================================================
template <typename SrcT>
__aicore__ inline void doEqHalfLike(
    AscendC::LocalTensor<SrcT> &x, AscendC::LocalTensor<SrcT> &y,
    AscendC::LocalTensor<int32_t> &z,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &fBuf,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &mBuf,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &oBuf,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &nBuf,
    int64_t len)
{
    AscendC::LocalTensor<float> w = fBuf.Get<float>(len * 2);
    AscendC::LocalTensor<float> xFp32 = w, yFp32 = w[len];
    AscendC::Cast(xFp32, x, AscendC::RoundMode::CAST_NONE, len);
    AscendC::Cast(yFp32, y, AscendC::RoundMode::CAST_NONE, len);
    doEqT(xFp32, yFp32, z, mBuf, oBuf, nBuf, len);
}

// ============================================================================
// Int8/Uint8: Cast to half → float32 → Compare
// ============================================================================
template <typename SrcT>
__aicore__ inline void doEqIntLike(
    AscendC::LocalTensor<SrcT> &x, AscendC::LocalTensor<SrcT> &y,
    AscendC::LocalTensor<int32_t> &z,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &hBufX,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &hBufY,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &fBuf,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &mBuf,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &oBuf,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &nBuf,
    int64_t len)
{
    AscendC::LocalTensor<half> xH = hBufX.Get<half>(len);
    AscendC::LocalTensor<half> yH = hBufY.Get<half>(len);
    AscendC::Cast(xH, x, AscendC::RoundMode::CAST_NONE, len);
    AscendC::Cast(yH, y, AscendC::RoundMode::CAST_NONE, len);
    doEqHalfLike(xH, yH, z, fBuf, mBuf, oBuf, nBuf, len);
}

// ============================================================================
// Specialized kernel structs
// ============================================================================

class KernelEqualBase {
public:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> qX, qY;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> qZ;
    AscendC::TBuf<AscendC::TPosition::VECCALC> mBuf, oBuf, nBuf; // mask, ones, zeros
    int64_t blockLen, tileLen;

    __aicore__ inline void setupBuffers(int64_t tlen) {
        tileLen = tlen;
        int64_t mLen = maskLen(tlen);
        pipe.InitBuffer(mBuf, mLen * sizeof(uint8_t));
        pipe.InitBuffer(oBuf, tlen * sizeof(int32_t));
        pipe.InitBuffer(nBuf, tlen * sizeof(int32_t));
    }
    __aicore__ inline void processLoop(
        void (*copyIn)(KernelEqualBase*, int64_t, int64_t),
        void (*compute)(KernelEqualBase*, int64_t, int64_t),
        void (*copyOut)(KernelEqualBase*, int64_t, int64_t))
    {
        int64_t tn = (blockLen + tileLen - 1) / tileLen;
        int64_t tail = blockLen - (tn - 1) * tileLen;
        for (int64_t i = 0; i < tn; ++i) {
            int64_t cur = (i == tn - 1) ? tail : tileLen;
            copyIn(this, i, cur);
            compute(this, i, cur);
            copyOut(this, i, cur);
        }
    }
    __aicore__ inline void copyOutI32(int64_t p, int64_t len, AscendC::GlobalTensor<int32_t> &gZ) {
        AscendC::LocalTensor<int32_t> z = qZ.DeQue<int32_t>();
        AscendC::DataCopyExtParams cp{1, (uint32_t)(len * 4), 0, 0, 0};
        AscendC::DataCopyPad(gZ[p * tileLen], z, cp);
        qZ.FreeTensor(z);
    }
};

#define KERNEL_COPYIN(T, gX, gY) \
    static void fi(KernelEqualBase *self, int64_t p, int64_t len) { \
        auto *k = dynamic_cast<KernelEq##T*>(self); \
        AscendC::LocalTensor<T> x = k->qX.AllocTensor<T>(); \
        copyGmToUb(x, k->gX, p * k->tileLen, len); k->qX.EnQue(x); \
        AscendC::LocalTensor<T> y = k->qY.AllocTensor<T>(); \
        copyGmToUb(y, k->gY, p * k->tileLen, len); k->qY.EnQue(y); \
    }

