template <typename T, typename SrcT = T>
struct KernelEq {
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> qX, qY;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> qZ;
    AscendC::TBuf<AscendC::TPosition::VECCALC> mBuf, oBuf, nBuf;
    AscendC::TBuf<AscendC::TPosition::VECCALC> fBuf;
    AscendC::TBuf<AscendC::TPosition::VECCALC> hBufX, hBufY; // only for int-like
    AscendC::GlobalTensor<T> gX, gY;
    AscendC::GlobalTensor<int32_t> gZ;
