    __aicore__ inline void init(GM_ADDR in1, GM_ADDR in2, GM_ADDR out,
                                 int64_t fn, int64_t fl, int64_t tl, int64_t tlen) {
        int64_t bidx = AscendC::GetBlockIdx();
        int64_t sz = sizeof(T);
        if (bidx < fn) {
            bLen = fl; int64_t off = fl * bidx;
            gX.SetGlobalBuffer((__gm__ T*)in1 + off, fl);
            gY.SetGlobalBuffer((__gm__ T*)in2 + off, fl);
            gZ.SetGlobalBuffer((__gm__ int32_t*)out + off, fl);
        } else {
            bLen = tl; int64_t ti = bidx - fn; int64_t off = fl * fn + tl * ti;
            gX.SetGlobalBuffer((__gm__ T*)in1 + off, tl);
            gY.SetGlobalBuffer((__gm__ T*)in2 + off, tl);
            gZ.SetGlobalBuffer((__gm__ int32_t*)out + off, tl);
        }
        tLenVal = tlen;
        pipe.InitBuffer(qX, BUFFER_NUM, tlen * sz);
        pipe.InitBuffer(qY, BUFFER_NUM, tlen * sz);
        pipe.InitBuffer(qZ, BUFFER_NUM, tlen * 4);
        int64_t mLen = maskLen(tlen);
        pipe.InitBuffer(mBuf, mLen);
        pipe.InitBuffer(oBuf, tlen * 4);
        pipe.InitBuffer(nBuf, tlen * 4);
        needCast = false; needHalfCast = false;
        if constexpr (std::is_same_v<T, half> || std::is_same_v<T, bfloat16_t>) {
            needCast = true;
            pipe.InitBuffer(fBuf, tlen * 4 * 2);
        }
        if constexpr (std::is_same_v<T, int8_t> || std::is_same_v<T, uint8_t>) {
            needHalfCast = true;
            pipe.InitBuffer(hBufX, tlen * sizeof(half));
            pipe.InitBuffer(hBufY, tlen * sizeof(half));
            pipe.InitBuffer(fBuf, tlen * 4 * 2);
        }
    }

    __aicore__ inline void process() {
        int64_t tn = (bLen + tLenVal - 1) / tLenVal;
        int64_t tail = bLen - (tn - 1) * tLenVal;
        for (int64_t i = 0; i < tn; ++i) {
            int64_t cur = (i == tn - 1) ? tail : tLenVal;
            copyIn(i, cur); compute(cur); copyOut(i, cur);
        }
    }

    __aicore__ inline void copyIn(int64_t p, int64_t len) {
        AscendC::LocalTensor<T> x = qX.AllocTensor<T>();
        AscendC::DataCopyExtParams cp{1, (uint32_t)(len * sizeof(T)), 0, 0, 0};
        AscendC::DataCopyPadExtParams<T> pp{true, 0, 0, static_cast<T>(0)};
        AscendC::DataCopyPad(x, gX[p * tLenVal], cp, pp); qX.EnQue(x);
        AscendC::LocalTensor<T> y = qY.AllocTensor<T>();
        AscendC::DataCopyPad(y, gY[p * tLenVal], cp, pp); qY.EnQue(y);
    }

    __aicore__ inline void compute(int64_t len) {
        AscendC::LocalTensor<T> x = qX.DeQue<T>();
        AscendC::LocalTensor<T> y = qY.DeQue<T>();
        AscendC::LocalTensor<int32_t> z = qZ.AllocTensor<int32_t>();
        if constexpr (std::is_same_v<T, float> || std::is_same_v<T, int32_t>) {
            doEqT(x, y, z, mBuf, oBuf, nBuf, len);
        } else if constexpr (std::is_same_v<T, half> || std::is_same_v<T, bfloat16_t>) {
            doEqHalfLike(x, y, z, fBuf, mBuf, oBuf, nBuf, len);
        } else {
            AscendC::LocalTensor<half> xH = hBufX.Get<half>(len);
            AscendC::LocalTensor<half> yH = hBufY.Get<half>(len);
            AscendC::Cast(xH, x, AscendC::RoundMode::CAST_NONE, len);
            AscendC::Cast(yH, y, AscendC::RoundMode::CAST_NONE, len);
            doEqHalfLike(xH, yH, z, fBuf, mBuf, oBuf, nBuf, len);
        }
        qZ.EnQue<int32_t>(z); qX.FreeTensor(x); qY.FreeTensor(y);
    }

    __aicore__ inline void copyOut(int64_t p, int64_t len) {
        AscendC::LocalTensor<int32_t> z = qZ.DeQue<int32_t>();
        AscendC::DataCopyExtParams cp{1, (uint32_t)(len * 4), 0, 0, 0};
        AscendC::DataCopyPad(gZ[p * tLenVal], z, cp); qZ.FreeTensor(z);
    }
};

__aicore__ void equal_kernel(
    GM_ADDR input1, GM_ADDR input2, GM_ADDR output,
    int64_t fN, int64_t fL, int64_t tL, int64_t tLen,
    int64_t dSize, int64_t dCat)
{
    if (dCat == 0) {
        KernelEq<half> op; op.init(input1, input2, output, fN, fL, tL, tLen); op.process();
    } else if (dCat == 1) {
        KernelEq<float> op; op.init(input1, input2, output, fN, fL, tL, tLen); op.process();
    } else if (dCat == 2) {
        KernelEq<bfloat16_t> op; op.init(input1, input2, output, fN, fL, tL, tLen); op.process();
    } else if (dCat == 3) {
        KernelEq<int8_t> op; op.init(input1, input2, output, fN, fL, tL, tLen); op.process();
    } else if (dCat == 4) {
        KernelEq<uint8_t> op; op.init(input1, input2, output, fN, fL, tL, tLen); op.process();
    } else {
        KernelEq<int32_t> op; op.init(input1, input2, output, fN, fL, tL, tLen); op.process();
    }
}
