#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

// Float32 / Int32: compute equality as 1 - min(1, |x - y|)
// All computation on float32 or int32 (casts done before calling)
template <typename T>
__aicore__ inline void computeEqSubAbs(
    AscendC::LocalTensor<T> &x, AscendC::LocalTensor<T> &y,
    AscendC::LocalTensor<T> &diff, AscendC::LocalTensor<T> &ones,
    int64_t len)
{
    AscendC::Sub(diff, x, y, len);
    AscendC::Abs(diff, diff, len);
    AscendC::Duplicate(ones, (T)1, len);
    AscendC::Min(diff, diff, ones, len);
    AscendC::Sub(ones, ones, diff, len);
}

template <typename SrcT>
struct KernelEqual {
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> qX, qY;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> qZ;
    AscendC::TBuf<AscendC::TPosition::VECCALC> wBuf;
    AscendC::TBuf<AscendC::TPosition::VECCALC> cBuf;  // cast buffer for half/int-like
    AscendC::GlobalTensor<SrcT> gX, gY;
    AscendC::GlobalTensor<int32_t> gZ;
    int64_t bLen, tLen;

    __aicore__ inline void init(GM_ADDR in1, GM_ADDR in2, GM_ADDR out,
                                 int64_t fn, int64_t fl, int64_t tl, int64_t tlen) {
        int64_t bidx = AscendC::GetBlockIdx();
        if (bidx < fn) {
            bLen = fl; int64_t off = fl * bidx;
            gX.SetGlobalBuffer((__gm__ SrcT*)in1 + off, fl);
            gY.SetGlobalBuffer((__gm__ SrcT*)in2 + off, fl);
            gZ.SetGlobalBuffer((__gm__ int32_t*)out + off, fl);
        } else {
            bLen = tl; int64_t ti = bidx - fn; int64_t off = fl * fn + tl * ti;
            gX.SetGlobalBuffer((__gm__ SrcT*)in1 + off, tl);
            gY.SetGlobalBuffer((__gm__ SrcT*)in2 + off, tl);
            gZ.SetGlobalBuffer((__gm__ int32_t*)out + off, tl);
        }
        tLen = tlen;

        pipe.InitBuffer(qX, BUFFER_NUM, tlen * sizeof(SrcT));
        pipe.InitBuffer(qY, BUFFER_NUM, tlen * sizeof(SrcT));
        pipe.InitBuffer(qZ, BUFFER_NUM, tlen * sizeof(int32_t));

        if constexpr (std::is_same_v<SrcT, float> || std::is_same_v<SrcT, int32_t>) {
            // diff + ones = 2 * tileLen * sizeof(float/int32)
            pipe.InitBuffer(wBuf, tlen * sizeof(SrcT) * 2);
        } else if constexpr (std::is_same_v<SrcT, half> || std::is_same_v<SrcT, bfloat16_t>) {
            // cast to float32: xFp32+yFp32+diffFp32+onesFp32 = 4*tileLen*sizeof(float)
            pipe.InitBuffer(wBuf, tlen * sizeof(float) * 4);
        } else {
            // int8/uint8: cast to float32 through half
            // half: 2*tileLen*sizeof(half), float: 4*tileLen*sizeof(float)
            pipe.InitBuffer(wBuf, tlen * sizeof(float) * 4);
            pipe.InitBuffer(cBuf, tlen * sizeof(half) * 2);
        }
    }

    __aicore__ inline void process() {
        int64_t tn = (bLen + tLen - 1) / tLen;
        int64_t tail = bLen - (tn - 1) * tLen;
        for (int64_t i = 0; i < tn; ++i) {
            int64_t cur = (i == tn - 1) ? tail : tLen;
            copyIn(i, cur); compute(cur); copyOut(i, cur);
        }
    }

    __aicore__ inline void copyIn(int64_t p, int64_t len) {
        AscendC::LocalTensor<SrcT> x = qX.AllocTensor<SrcT>();
        AscendC::DataCopyExtParams cp{1, (uint32_t)(len * sizeof(SrcT)), 0, 0, 0};
        AscendC::DataCopyPadExtParams<SrcT> pp{true, 0, 0, static_cast<SrcT>(0)};
        AscendC::DataCopyPad(x, gX[p * tLen], cp, pp); qX.EnQue(x);
        AscendC::LocalTensor<SrcT> y = qY.AllocTensor<SrcT>();
        AscendC::DataCopyPad(y, gY[p * tLen], cp, pp); qY.EnQue(y);
    }

    __aicore__ inline void compute(int64_t len) {
        AscendC::LocalTensor<SrcT> x = qX.DeQue<SrcT>();
        AscendC::LocalTensor<SrcT> y = qY.DeQue<SrcT>();
        AscendC::LocalTensor<int32_t> z = qZ.AllocTensor<int32_t>();

        if constexpr (std::is_same_v<SrcT, float>) {
            AscendC::LocalTensor<float> w = wBuf.Get<float>(len * 2);
            AscendC::LocalTensor<float> diff = w, ones = w[len];
            computeEqSubAbs(x, y, diff, ones, len);
            AscendC::Cast(z, ones, AscendC::RoundMode::CAST_RINT, len);
        } else if constexpr (std::is_same_v<SrcT, int32_t>) {
            AscendC::LocalTensor<int32_t> w = wBuf.Get<int32_t>(len * 2);
            AscendC::LocalTensor<int32_t> diff = w, ones = w[len];
            computeEqSubAbs(x, y, diff, ones, len);
            // result already in int32, just copy to output
            AscendC::Duplicate(z, ones, len);
        } else if constexpr (std::is_same_v<SrcT, half> || std::is_same_v<SrcT, bfloat16_t>) {
            // Cast half → float32 → SubAbs → Cast back
            AscendC::LocalTensor<float> w = wBuf.Get<float>(len * 4);
            AscendC::LocalTensor<float> xFp32 = w, yFp32 = w[len];
            AscendC::LocalTensor<float> diff = w[len * 2], ones = w[len * 3];
            AscendC::Cast(xFp32, x, AscendC::RoundMode::CAST_NONE, len);
            AscendC::Cast(yFp32, y, AscendC::RoundMode::CAST_NONE, len);
            computeEqSubAbs(xFp32, yFp32, diff, ones, len);
            AscendC::Cast(z, ones, AscendC::RoundMode::CAST_RINT, len);
        } else {
            // int8/uint8: Cast half from cBuf, then half→float32
            AscendC::LocalTensor<half> hw = cBuf.Get<half>(len * 2);
            AscendC::LocalTensor<half> xH = hw, yH = hw[len];
