// ============================================================================
// float32 equal kernel: Sub -> Abs -> Min -> Sub
// ============================================================================
struct EqualFloat {
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> qX, qY;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> qZ;
    AscendC::TBuf<AscendC::TPosition::VECCALC> wBuf;
    AscendC::GlobalTensor<float> gX, gY;
    AscendC::GlobalTensor<int32_t> gZ;
    int64_t bLen, tLen;

    __aicore__ inline void init(GM_ADDR in1, GM_ADDR in2, GM_ADDR out,
                                 int64_t fn, int64_t fl, int64_t tl, int64_t tlen);
    __aicore__ inline void process();
    __aicore__ inline void copyIn(int64_t p, int64_t l);
    __aicore__ inline void compute(int64_t l);
    __aicore__ inline void copyOut(int64_t p, int64_t l);
};

__aicore__ inline void EqualFloat::init(GM_ADDR in1, GM_ADDR in2, GM_ADDR out,
                                         int64_t fn, int64_t fl, int64_t tl, int64_t tlen) {
    int64_t bidx = AscendC::GetBlockIdx();
    if (bidx < fn) { bLen = fl; int64_t off = fl * bidx;
        gX.SetGlobalBuffer((__gm__ float*)in1+off, fl);
        gY.SetGlobalBuffer((__gm__ float*)in2+off, fl);
        gZ.SetGlobalBuffer((__gm__ int32_t*)out+off, fl);
    } else { bLen = tl; int64_t ti = bidx - fn; int64_t off = fl*fn + tl*ti;
        gX.SetGlobalBuffer((__gm__ float*)in1+off, tl);
        gY.SetGlobalBuffer((__gm__ float*)in2+off, tl);
        gZ.SetGlobalBuffer((__gm__ int32_t*)out+off, tl);
    }
    tLen = tlen;
    pipe.InitBuffer(qX, BUFFER_NUM, tlen*4);
    pipe.InitBuffer(qY, BUFFER_NUM, tlen*4);
    pipe.InitBuffer(qZ, BUFFER_NUM, tlen*4);
    pipe.InitBuffer(wBuf, tlen*8);  // diff(l*4) + ones(l*4)
