__aicore__ inline void EqualFloat::process() {
    int64_t tn = (bLen + tLen - 1) / tLen;
    int64_t tail = bLen - (tn - 1) * tLen;
    for (int64_t i = 0; i < tn; ++i) {
        int64_t cur = (i == tn - 1) ? tail : tLen;
