    AscendC::DataCopyPadExtParams<float> pp{true, 0, 0, 0.0f};
    AscendC::DataCopyPad(x, gX[p*tLen], cp, pp); qX.EnQue(x);
    AscendC::LocalTensor<float> y = qY.AllocTensor<float>();
