    AscendC::DataCopyExtParams cp{1, (uint32_t)(l*sizeof(SrcT)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<SrcT> pp{true, 0, 0, static_cast<SrcT>(0)};
    AscendC::DataCopyPad(x, gX[p*tLen], cp, pp); qX.EnQue(x);
    AscendC::LocalTensor<SrcT> y = qY.AllocTensor<SrcT>();
    AscendC::DataCopyPad(y, gY[p*tLen], cp, pp); qY.EnQue(y);
}

template <typename SrcT>
__aicore__ inline void EqualIntLike<SrcT>::compute(int64_t l) {
    AscendC::LocalTensor<SrcT> x = qX.DeQue<SrcT>();
    AscendC::LocalTensor<SrcT> y = qY.DeQue<SrcT>();
    AscendC::LocalTensor<int32_t> z = qZ.AllocTensor<int32_t>();
