    AscendC::Cast(yF32, yH, AscendC::RoundMode::CAST_NONE, l);
    AscendC::Sub(diff, xF32, yF32, l);
    AscendC::Abs(diff, diff, l);
    AscendC::Duplicate(onesF, 1.0f, l);
