#include "kernel_operator.h"

constexpr int32_t NB = 2;
using namespace AscendC;

// ============================================================================
// Kernel: float32 + int32 direct comparison  (Sub/Abs/Min/Sub)
// ============================================================================
template <typename T>
struct EqDirect {
    TPipe p; TQue<TPosition::VECIN, NB> qX, qY;
    TQue<TPosition::VECOUT, NB> qZ; TBuf<TPosition::VECCALC> wb;
    GlobalTensor<T> gX, gY; GlobalTensor<int32_t> gZ; int64_t bL, tL;

    __aicore__ inline void init(GM_ADDR in1, GM_ADDR in2, GM_ADDR out,
                                 int64_t fn, int64_t fl, int64_t tl, int64_t tlen) {
        int64_t bidx = GetBlockIdx();
        if (bidx < fn) { bL = fl; int64_t off = fl*bidx;
            gX.SetGlobalBuffer((__gm__ T*)in1+off,fl); gY.SetGlobalBuffer((__gm__ T*)in2+off,fl);
            gZ.SetGlobalBuffer((__gm__ int32_t*)out+off,fl);
        } else { bL = tl; int64_t ti = bidx-fn; int64_t off = fl*fn + tl*ti;
            gX.SetGlobalBuffer((__gm__ T*)in1+off,tl); gY.SetGlobalBuffer((__gm__ T*)in2+off,tl);
            gZ.SetGlobalBuffer((__gm__ int32_t*)out+off,tl);
        }
        tL = tlen; p.InitBuffer(qX,NB,tlen*sizeof(T)); p.InitBuffer(qY,NB,tlen*sizeof(T));
        p.InitBuffer(qZ,NB,tlen*4); p.InitBuffer(wb,tlen*sizeof(T)*2);
    }

    __aicore__ inline void process() {
        int64_t tn = (bL+tL-1)/tL, tail = bL-(tn-1)*tL;
        for (int64_t i=0; i<tn; ++i) { int64_t c=i==tn-1?tail:tL; ci(i,c); cm(c); co(i,c); }
    }

    __aicore__ inline void ci(int64_t pr, int64_t l) {
        { auto x=qX.AllocTensor<T>(); DataCopyExtParams cp{1,(uint32_t)(l*sizeof(T)),0,0,0};
          DataCopyPadExtParams<T> pp{true,0,0,static_cast<T>(0)};
          DataCopyPad(x,gX[pr*tL],cp,pp); qX.EnQue(x); }
        { auto y=qY.AllocTensor<T>(); DataCopyExtParams cp{1,(uint32_t)(l*sizeof(T)),0,0,0};
          DataCopyPadExtParams<T> pp{true,0,0,static_cast<T>(0)};
          DataCopyPad(y,gY[pr*tL],cp,pp); qY.EnQue(y); }
    }

    __aicore__ inline void cm(int64_t l) {
        auto x=qX.DeQue<T>(); auto y=qY.DeQue<T>(); auto z=qZ.AllocTensor<int32_t>();
        auto w=wb.Get<T>(l*2); auto d=w, o=w[l];
        Sub(d,x,y,l); Abs(d,d,l); Duplicate(o,(T)1,l); Min(d,d,o,l); Sub(o,o,d,l);
        if constexpr (std::is_same_v<T,float>) { Cast(z,o,RoundMode::CAST_RINT,l); }
        else { Sub(z,o,d,l); Sub(z,o,z,l); Add(z,o,z,l); } // z = o (real value already computed)
        qZ.EnQue<int32_t>(z); qX.FreeTensor(x); qY.FreeTensor(y);
    }

    __aicore__ inline void co(int64_t pr, int64_t l) {
        auto z=qZ.DeQue<int32_t>(); DataCopyExtParams cp{1,(uint32_t)(l*4),0,0,0};
        DataCopyPad(gZ[pr*tL],z,cp); qZ.FreeTensor(z);
    }
};

