#include "kernel_operator.h"

constexpr int32_t NB = 2;

// Helper: compute abs(d) = max(d, -d) using Sub+Max (avoids Abs API on half)
template <typename T>
__aicore__ inline void absViaMax(
    AscendC::LocalTensor<T> &d, AscendC::LocalTensor<T> &n,
    AscendC::LocalTensor<T> &z, int64_t l)
{
    AscendC::Duplicate(z, (T)0, l);
    AscendC::Sub(n, z, d, l);
    AscendC::Max(d, d, n, l);
}

// ============================================================================
// float32 + int32 direct comparison: Sub/AbsViaMax/Min/Sub
// ============================================================================
template <typename T>
struct EqDirect {
    AscendC::TPipe p;
    AscendC::TQue<AscendC::TPosition::VECIN, NB> qX, qY;
    AscendC::TQue<AscendC::TPosition::VECOUT, NB> qZ;
    AscendC::TBuf<AscendC::TPosition::VECCALC> wb;
    AscendC::GlobalTensor<T> gX, gY;
    AscendC::GlobalTensor<int32_t> gZ;
    int64_t bL, tL;

    __aicore__ inline void init(GM_ADDR in1, GM_ADDR in2, GM_ADDR out,
                                 int64_t fn, int64_t fl, int64_t tl, int64_t tlen) {
        int64_t bidx = AscendC::GetBlockIdx();
        if (bidx < fn) { bL = fl; int64_t off = fl*bidx;
            gX.SetGlobalBuffer((__gm__ T*)in1+off,fl); gY.SetGlobalBuffer((__gm__ T*)in2+off,fl);
            gZ.SetGlobalBuffer((__gm__ int32_t*)out+off,fl);
        } else { bL = tl; int64_t ti = bidx-fn; int64_t off = fl*fn+tl*ti;
            gX.SetGlobalBuffer((__gm__ T*)in1+off,tl); gY.SetGlobalBuffer((__gm__ T*)in2+off,tl);
            gZ.SetGlobalBuffer((__gm__ int32_t*)out+off,tl);
        }
        tL = tlen; p.InitBuffer(qX,NB,tlen*sizeof(T)); p.InitBuffer(qY,NB,tlen*sizeof(T));
        p.InitBuffer(qZ,NB,tlen*4);
        // 4 buffers: diff, neg, ones, zeros
        p.InitBuffer(wb,tlen*sizeof(T)*4);
    }

    __aicore__ inline void process() {
        int64_t tn=(bL+tL-1)/tL, tail=bL-(tn-1)*tL;
        for (int64_t i=0; i<tn; ++i) { int64_t c=i==tn-1?tail:tL; ci(i,c); cm(c); co(i,c); }
    }

    __aicore__ inline void ci(int64_t pr, int64_t l) {
        { auto x=qX.AllocTensor<T>(); AscendC::DataCopyExtParams cp{1,(uint32_t)(l*sizeof(T)),0,0,0};
          AscendC::DataCopyPadExtParams<T> pp{true,0,0,static_cast<T>(0)};
          AscendC::DataCopyPad(x,gX[pr*tL],cp,pp); qX.EnQue(x); }
        { auto y=qY.AllocTensor<T>(); AscendC::DataCopyExtParams cp{1,(uint32_t)(l*sizeof(T)),0,0,0};
          AscendC::DataCopyPadExtParams<T> pp{true,0,0,static_cast<T>(0)};
          AscendC::DataCopyPad(y,gY[pr*tL],cp,pp); qY.EnQue(y); }
    }

    __aicore__ inline void cm(int64_t l) {
        auto x=qX.DeQue<T>(); auto y=qY.DeQue<T>(); auto z=qZ.AllocTensor<int32_t>();
        auto w=wb.Get<T>(l*4);
        auto d=w, n=w[l], o=w[l*2], zt=w[l*3];
        AscendC::Sub(d,x,y,l);
        absViaMax(d,n,zt,l);
        AscendC::Duplicate(o,(T)1,l);
        AscendC::Min(d,d,o,l);
        if constexpr (std::is_same_v<T,float>) {
            AscendC::Sub(o,o,d,l);
            AscendC::Cast(z,o,AscendC::RoundMode::CAST_RINT,l);
        } else {
            AscendC::Sub(z,o,d,l);
        }
        qZ.EnQue<int32_t>(z); qX.FreeTensor(x); qY.FreeTensor(y);
    }

    __aicore__ inline void co(int64_t pr, int64_t l) {
        auto z=qZ.DeQue<int32_t>(); AscendC::DataCopyExtParams cp{1,(uint32_t)(l*4),0,0,0};
        AscendC::DataCopyPad(gZ[pr*tL],z,cp); qZ.FreeTensor(z);
    }
};

// ============================================================================
// half/bf16: Cast->float32 -> Sub/Max/Min/Sub -> Cast->int32
// ============================================================================
template <typename SrcT>
struct EqFp16Like {
    AscendC::TPipe p;
    AscendC::TQue<AscendC::TPosition::VECIN, NB> qX, qY;
    AscendC::TQue<AscendC::TPosition::VECOUT, NB> qZ;
    AscendC::TBuf<AscendC::TPosition::VECCALC> wb;
    AscendC::GlobalTensor<SrcT> gX, gY;
    AscendC::GlobalTensor<int32_t> gZ;
    int64_t bL, tL;

    __aicore__ inline void init(GM_ADDR in1, GM_ADDR in2, GM_ADDR out,
                                 int64_t fn, int64_t fl, int64_t tl, int64_t tlen) {
        int64_t bidx = AscendC::GetBlockIdx();
        if (bidx < fn) { bL = fl; int64_t off = fl*bidx;
            gX.SetGlobalBuffer((__gm__ SrcT*)in1+off,fl); gY.SetGlobalBuffer((__gm__ SrcT*)in2+off,fl);
            gZ.SetGlobalBuffer((__gm__ int32_t*)out+off,fl);
        } else { bL = tl; int64_t ti = bidx-fn; int64_t off = fl*fn+tl*ti;
            gX.SetGlobalBuffer((__gm__ SrcT*)in1+off,tl); gY.SetGlobalBuffer((__gm__ SrcT*)in2+off,tl);
            gZ.SetGlobalBuffer((__gm__ int32_t*)out+off,tl);
        }
        tL = tlen;
        p.InitBuffer(qX,NB,tlen*sizeof(SrcT)); p.InitBuffer(qY,NB,tlen*sizeof(SrcT));
        p.InitBuffer(qZ,NB,tlen*4);
        // 6 float32: xf, yf, diff, neg, ones, zeros
        p.InitBuffer(wb,tlen*sizeof(float)*6);
