        AscendC::Sub(d,x,y,l); AscendC::Duplicate(zt,0.0f,l); AscendC::Sub(n,zt,d,l);
        AscendC::Max(d,d,n,l); AscendC::Duplicate(o,1.0f,l); AscendC::Min(d,d,o,l);
        AscendC::Sub(o,o,d,l); AscendC::Cast(z,o,AscendC::RoundMode::CAST_RINT,l);
        qZ.EnQue<int32_t>(z); qX.FreeTensor(x); qY.FreeTensor(y);
    }
    __aicore__ inline void co(int64_t pr, int64_t l) {
        auto z=qZ.DeQue<int32_t>(); AscendC::DataCopyExtParams cp{1,(uint32_t)(l*4),0,0,0};
