            gZ.SetGlobalBuffer((__gm__ int32_t*)o+off,fl);
        } else { bL = tl; int64_t ti = bidx-fn; int64_t off = fl*fn+tl*ti;
            gX.SetGlobalBuffer((__gm__ SrcT*)i1+off,tl); gY.SetGlobalBuffer((__gm__ SrcT*)i2+off,tl);
            gZ.SetGlobalBuffer((__gm__ int32_t*)o+off,tl);
        }
        tL = tlen;
        p.InitBuffer(qX,NB,tlen*sz); p.InitBuffer(qY,NB,tlen*sz); p.InitBuffer(qZ,NB,tlen*4);
        p.InitBuffer(cBuf,tlen*8);  // 2x tileLen floats for xFp32, yFp32
        p.InitBuffer(wBuf,tlen*16); // 4x tileLen floats for diff, neg, ones, zero
    }
    __aicore__ inline void process() { int64_t tn=(bL+tL-1)/tL, tail=bL-(tn-1)*tL;
        for (int64_t i=0; i<tn; ++i) { int64_t c=i==tn-1?tail:tL; ci(i,c); cm(c); co(i,c); } }
    __aicore__ inline void ci(int64_t pr, int64_t l) {
