          AscendC::DataCopyPadExtParams<SrcT> pp{true,0,0,static_cast<SrcT>(0)}; AscendC::DataCopyPad(x,gX[pr*tL],cp,pp); qX.EnQue(x); }
        { auto y=qY.AllocTensor<SrcT>(); AscendC::DataCopyExtParams cp{1,(uint32_t)(l*sz),0,0,0};
          AscendC::DataCopyPadExtParams<SrcT> pp{true,0,0,static_cast<SrcT>(0)}; AscendC::DataCopyPad(y,gY[pr*tL],cp,pp); qY.EnQue(y); }
    }
    __aicore__ inline void cm(int64_t l) {
