        AscendC::Max(d,d,n,l); AscendC::Duplicate(o,1.0f,l); AscendC::Min(d,d,o,l);
        AscendC::Sub(o,o,d,l); AscendC::Cast(z,o,AscendC::RoundMode::CAST_RINT,l);
